[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="Engineering insights, product updates, and community stories from DeployCloud — the cloud deployment platform." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    /* ─── Design Tokens (OKLCH) ───────────────────────────────────────────── */
    :root {
      /* Brand */
      --color-accent:       oklch(52% 0.24 252);   /* #0072F5 electric blue */
      --color-accent-light: oklch(95% 0.04 252);   /* soft blue tint */
      --color-accent-hover: oklch(45% 0.26 252);   /* darker blue */

      /* Text */
      --color-text-primary:   oklch(11% 0.01 265); /* #171717 near-black */
      --color-text-secondary: oklch(44% 0.01 265); /* mid-gray */
      --color-text-muted:     oklch(60% 0.01 265); /* light-gray */

      /* Surfaces */
      --color-bg:        oklch(98.5% 0.003 265);   /* #FAFAFA */
      --color-surface:   oklch(100% 0 0);           /* white card */
      --color-border:    oklch(91% 0.005 265);      /* subtle border */
      --color-border-hov:oklch(80% 0.008 265);

      /* Typography */
      --font: 'Inter', system-ui, -apple-system, sans-serif;

      /* Spacing scale (4px base) */
      --sp-1: 4px;  --sp-2: 8px;  --sp-3: 12px;  --sp-4: 16px;
      --sp-5: 20px; --sp-6: 24px; --sp-8: 32px;  --sp-10: 40px;
      --sp-12: 48px;--sp-16: 64px;--sp-20: 80px;

      /* Radius */
      --r-sm: 6px; --r-md: 10px; --r-lg: 16px; --r-pill: 999px;

      /* Shadow */
      --shadow-card: 0 1px 3px oklch(0% 0 0 / .07), 0 4px 12px oklch(0% 0 0 / .05);
      --shadow-card-hover: 0 4px 16px oklch(0% 0 0 / .10), 0 1px 4px oklch(0% 0 0 / .06);
      --shadow-dropdown: 0 8px 32px oklch(0% 0 0 / .12), 0 2px 8px oklch(0% 0 0 / .06);

      /* Transitions */
      --transition: 150ms cubic-bezier(.4,0,.2,1);
    }

    /* ─── Reset ───────────────────────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      background: var(--color-bg);
      color: var(--color-text-primary);
      font-size: 15px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    ul, ol { list-style: none; }

    /* ─── Layout ──────────────────────────────────────────────────────────── */
    .container {
      width: 100%;
      max-width: 1200px;
      margin-inline: auto;
      padding-inline: var(--sp-6);
    }

    /* ─── NAV ─────────────────────────────────────────────────────────────── */
    .nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: oklch(100% 0 0 / .92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--color-border);
    }
    .nav-inner {
      display: flex;
      align-items: center;
      height: 60px;
      gap: var(--sp-2);
    }
    .nav-logo {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      font-weight: 700;
      font-size: 17px;
      letter-spacing: -.3px;
      color: var(--color-text-primary);
      margin-right: var(--sp-4);
      flex-shrink: 0;
    }
    .nav-logo svg { width: 28px; height: 28px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: var(--sp-1);
      flex: 1;
    }
    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: var(--sp-2) var(--sp-3);
      font-size: 14px;
      font-weight: 500;
      color: var(--color-text-secondary);
      border-radius: var(--r-sm);
      transition: color var(--transition), background var(--transition);
      white-space: nowrap;
      position: relative;
    }
    .nav-link:hover, .nav-link.active { color: var(--color-text-primary); background: var(--color-border); }
    .nav-link svg { width: 14px; height: 14px; transition: transform var(--transition); }
    .nav-link:hover svg, .nav-link.dropdown-open svg { transform: rotate(180deg); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      margin-left: auto;
    }
    .btn-ghost {
      padding: 6px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--color-text-secondary);
      border-radius: var(--r-sm);
      transition: color var(--transition), background var(--transition);
    }
    .btn-ghost:hover { color: var(--color-text-primary); background: var(--color-border); }
    .btn-primary {
      padding: 6px 16px;
      font-size: 14px;
      font-weight: 600;
      color: #fff;
      background: var(--color-text-primary);
      border-radius: var(--r-sm);
      transition: background var(--transition), transform var(--transition);
    }
    .btn-primary:hover { background: oklch(22% 0.01 265); transform: translateY(-1px); }

    /* Dropdown */
    .dropdown-wrapper { position: relative; }
    .dropdown-menu {
      display: none;
      position: absolute;
      top: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--r-lg);
      box-shadow: var(--shadow-dropdown);
      padding: var(--sp-5);
      z-index: 200;
      animation: fadeDown .15s ease;
    }
    .dropdown-menu.open { display: flex; }
    @keyframes fadeDown {
      from { opacity: 0; transform: translateX(-50%) translateY(-6px); }
      to   { opacity: 1; transform: translateX(-50%) translateY(0); }
    }
    .dropdown-col {
      min-width: 200px;
      padding-inline: var(--sp-4);
    }
    .dropdown-col:not(:last-child) { border-right: 1px solid var(--color-border); }
    .dropdown-col-title {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--color-text-muted);
      margin-bottom: var(--sp-3);
    }
    .dropdown-item {
      display: block;
      padding: 7px var(--sp-3);
      border-radius: var(--r-sm);
      font-size: 13.5px;
      transition: background var(--transition), color var(--transition);
    }
    .dropdown-item:hover { background: var(--color-accent-light); color: var(--color-accent); }
    .dropdown-item-title { font-weight: 600; font-size: 13.5px; }
    .dropdown-item-desc { font-size: 11.5px; color: var(--color-text-muted); margin-top: 1px; }

    /* ─── HERO STRIP ──────────────────────────────────────────────────────── */
    .hero-strip {
      padding: var(--sp-16) 0 var(--sp-6);
    }
    .hero-strip h1 {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      letter-spacing: -.8px;
      line-height: 1.15;
      margin-bottom: var(--sp-3);
    }
    .hero-strip p {
      font-size: 17px;
      color: var(--color-text-secondary);
      max-width: 520px;
    }

    /* ─── FILTER BAR ──────────────────────────────────────────────────────── */
    .filter-bar {
      padding-block: var(--sp-6);
      border-bottom: 1px solid var(--color-border);
      margin-bottom: var(--sp-10);
    }
    .filter-inner {
      display: flex;
      align-items: center;
      gap: var(--sp-4);
      flex-wrap: wrap;
    }
    .filter-pills {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      flex-wrap: wrap;
      flex: 1;
    }
    .pill {
      display: inline-flex;
      align-items: center;
      padding: 6px 14px;
      font-size: 13px;
      font-weight: 500;
      border-radius: var(--r-pill);
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      color: var(--color-text-secondary);
      transition: all var(--transition);
      white-space: nowrap;
    }
    .pill:hover { border-color: var(--color-accent); color: var(--color-accent); }
    .pill.active {
      background: var(--color-text-primary);
      border-color: var(--color-text-primary);
      color: #fff;
    }
    .search-wrap {
      position: relative;
      flex-shrink: 0;
    }
    .search-icon {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      color: var(--color-text-muted);
      pointer-events: none;
    }
    .search-input {
      font-family: var(--font);
      font-size: 14px;
      padding: 8px 14px 8px 38px;
      border: 1px solid var(--color-border);
      border-radius: var(--r-pill);
      background: var(--color-surface);
      color: var(--color-text-primary);
      outline: none;
      width: 220px;
      transition: border-color var(--transition), box-shadow var(--transition);
    }
    .search-input::placeholder { color: var(--color-text-muted); }
    .search-input:focus {
      border-color: var(--color-accent);
      box-shadow: 0 0 0 3px oklch(52% 0.24 252 / .12);
    }

    /* ─── FEATURED SECTION ────────────────────────────────────────────────── */
    .section-label {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--color-text-muted);
      margin-bottom: var(--sp-5);
    }
    .featured-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto auto;
      gap: var(--sp-6);
      margin-bottom: var(--sp-16);
    }
    .featured-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--r-lg);
      overflow: hidden;
      transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
      display: flex;
      flex-direction: column;
    }
    .featured-card:hover {
      box-shadow: var(--shadow-card-hover);
      transform: translateY(-2px);
      border-color: var(--color-border-hov);
    }
    .featured-card.main {
      grid-column: 1 / 3;
      grid-row: 1;
      flex-direction: row;
      min-height: 280px;
    }
    .featured-card-visual {
      background: linear-gradient(135deg, oklch(14% 0.04 265) 0%, oklch(20% 0.06 252) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: var(--sp-8);
      position: relative;
      overflow: hidden;
    }
    .featured-card.main .featured-card-visual {
      flex: 0 0 42%;
      min-height: 280px;
    }
    .featured-card:not(.main) .featured-card-visual {
      height: 180px;
    }
    /* Decorative grid pattern */
    .featured-card-visual::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(oklch(100% 0 0 / .04) 1px, transparent 1px),
        linear-gradient(90deg, oklch(100% 0 0 / .04) 1px, transparent 1px);
      background-size: 24px 24px;
    }
    .featured-card-visual .stat-badge {
      position: relative;
      z-index: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: var(--sp-3);
    }
    .stat-big {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      color: #fff;
      letter-spacing: -1.5px;
      line-height: 1;
    }
    .stat-label {
      font-size: 13px;
      color: oklch(80% 0.05 252);
      font-weight: 500;
      text-align: center;
    }
    .stat-row {
      display: flex;
      gap: var(--sp-8);
      flex-wrap: wrap;
    }
    .stat-item {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }
    .stat-item .stat-big { font-size: clamp(22px, 3vw, 32px); }

    .featured-card-body {
      padding: var(--sp-6);
      display: flex;
      flex-direction: column;
      flex: 1;
    }
    .card-meta {
      display: flex;
      align-items: center;
      gap: var(--sp-3);
      margin-bottom: var(--sp-3);
    }
    .card-tag {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: .06em;
      text-transform: uppercase;
      color: var(--color-accent);
      background: var(--color-accent-light);
      padding: 3px 9px;
      border-radius: var(--r-pill);
    }
    .card-date {
      font-size: 12px;
      color: var(--color-text-muted);
    }
    .card-title {
      font-size: clamp(17px, 2vw, 21px);
      font-weight: 700;
      letter-spacing: -.3px;
      line-height: 1.3;
      margin-bottom: var(--sp-3);
      transition: color var(--transition);
    }
    .featured-card:hover .card-title { color: var(--color-accent); }
    .featured-card.main .card-title { font-size: clamp(20px, 2.5vw, 26px); }
    .card-excerpt {
      font-size: 14px;
      color: var(--color-text-secondary);
      line-height: 1.65;
      flex: 1;
      margin-bottom: var(--sp-5);
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .featured-card.main .card-excerpt { -webkit-line-clamp: 4; }
    .card-author {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      margin-top: auto;
    }
    .avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--color-accent) 0%, oklch(65% 0.18 200) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: #fff;
      flex-shrink: 0;
    }
    .avatar.alt  { background: linear-gradient(135deg, oklch(60% 0.18 30) 0%, oklch(70% 0.15 50) 100%); }
    .avatar.alt2 { background: linear-gradient(135deg, oklch(55% 0.20 150) 0%, oklch(65% 0.16 170) 100%); }
    .author-name {
      font-size: 12.5px;
      font-weight: 600;
      color: var(--color-text-primary);
    }

    /* ─── LATEST NEWS ─────────────────────────────────────────────────────── */
    .latest-news-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: var(--sp-6);
    }
    .latest-news-header h2 {
      font-size: 22px;
      font-weight: 700;
      letter-spacing: -.3px;
    }
    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--sp-5);
      margin-bottom: var(--sp-10);
    }
    .news-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--r-md);
      padding: var(--sp-5);
      display: flex;
      flex-direction: column;
      transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
      cursor: pointer;
    }
    .news-card:hover {
      box-shadow: var(--shadow-card-hover);
      transform: translateY(-2px);
      border-color: var(--color-border-hov);
    }
    .news-card .card-title {
      font-size: 15px;
      margin-bottom: var(--sp-2);
    }
    .news-card:hover .card-title { color: var(--color-accent); }
    .news-card .card-excerpt {
      font-size: 13px;
      -webkit-line-clamp: 2;
      margin-bottom: var(--sp-4);
    }
    .news-card .card-meta { margin-bottom: var(--sp-3); }
    .news-card .card-author { padding-top: var(--sp-3); border-top: 1px solid var(--color-border); }

    /* No-results */
    .no-results {
      display: none;
      grid-column: 1/-1;
      text-align: center;
      padding: var(--sp-16) var(--sp-6);
      color: var(--color-text-muted);
    }
    .no-results.visible { display: block; }
    .no-results p { font-size: 15px; margin-top: var(--sp-3); }
    .no-results-icon { font-size: 36px; margin-bottom: var(--sp-4); }

    /* Show more */
    .show-more-wrap {
      display: flex;
      justify-content: center;
      margin-bottom: var(--sp-20);
    }
    .btn-show-more {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      padding: 11px 28px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-text-primary);
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--r-pill);
      transition: all var(--transition);
    }
    .btn-show-more:hover {
      background: var(--color-text-primary);
      color: #fff;
      border-color: var(--color-text-primary);
      transform: translateY(-1px);
    }
    .btn-show-more.loading { opacity: .6; pointer-events: none; }

    /* ─── CTA BANNER ──────────────────────────────────────────────────────── */
    .cta-section {
      background: linear-gradient(135deg, oklch(14% 0.04 265) 0%, oklch(18% 0.08 252) 100%);
      border-radius: var(--r-lg);
      padding: var(--sp-12) var(--sp-8);
      margin-bottom: var(--sp-16);
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-10);
      align-items: center;
      position: relative;
      overflow: hidden;
    }
    .cta-section::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(oklch(100% 0 0 / .03) 1px, transparent 1px),
        linear-gradient(90deg, oklch(100% 0 0 / .03) 1px, transparent 1px);
      background-size: 28px 28px;
    }
    .cta-block { position: relative; z-index: 1; }
    .cta-block h2 {
      font-size: clamp(20px, 2.5vw, 28px);
      font-weight: 700;
      color: #fff;
      letter-spacing: -.3px;
      line-height: 1.3;
      margin-bottom: var(--sp-5);
    }
    .cta-block h2 strong { color: var(--color-accent); font-weight: 800; }
    .cta-divider {
      width: 1px;
      background: oklch(100% 0 0 / .12);
      align-self: stretch;
    }
    .cta-buttons {
      display: flex;
      gap: var(--sp-3);
      flex-wrap: wrap;
    }
    .btn-cta-primary {
      display: inline-flex;
      align-items: center;
      padding: 10px 22px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-text-primary);
      background: #fff;
      border-radius: var(--r-sm);
      transition: all var(--transition);
    }
    .btn-cta-primary:hover { background: oklch(96% 0 0); transform: translateY(-1px); }
    .btn-cta-secondary {
      display: inline-flex;
      align-items: center;
      padding: 10px 22px;
      font-size: 14px;
      font-weight: 600;
      color: #fff;
      background: oklch(100% 0 0 / .1);
      border: 1px solid oklch(100% 0 0 / .2);
      border-radius: var(--r-sm);
      transition: all var(--transition);
    }
    .btn-cta-secondary:hover { background: oklch(100% 0 0 / .16); }
    .enterprise-label {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: oklch(70% 0.08 252);
      margin-bottom: var(--sp-3);
    }
    .enterprise-desc {
      font-size: 14px;
      color: oklch(72% 0.02 265);
      margin-bottom: var(--sp-5);
      line-height: 1.6;
    }

    /* ─── FOOTER ──────────────────────────────────────────────────────────── */
    .footer {
      border-top: 1px solid var(--color-border);
      padding: var(--sp-16) 0 var(--sp-10);
      background: var(--color-surface);
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: var(--sp-8) var(--sp-6);
      margin-bottom: var(--sp-12);
    }
    .footer-col-title {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--color-text-primary);
      margin-bottom: var(--sp-4);
    }
    .footer-links { display: flex; flex-direction: column; gap: var(--sp-2); }
    .footer-link {
      font-size: 13.5px;
      color: var(--color-text-secondary);
      transition: color var(--transition);
    }
    .footer-link:hover { color: var(--color-accent); }
    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: var(--sp-6);
      border-top: 1px solid var(--color-border);
      gap: var(--sp-4);
      flex-wrap: wrap;
    }
    .footer-brand {
      display: flex;
      align-items: center;
      gap: var(--sp-2);
      font-weight: 700;
      font-size: 15px;
    }
    .footer-brand svg { width: 22px; height: 22px; }
    .status-pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 12.5px;
      color: oklch(48% 0.14 145);
      background: oklch(95% 0.04 145);
      padding: 4px 12px;
      border-radius: var(--r-pill);
    }
    .status-dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: oklch(55% 0.18 145);
      animation: pulse 2s infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: .5; }
    }
    .footer-copy {
      font-size: 12px;
      color: var(--color-text-muted);
    }

    /* ─── SECTION DIVIDER ─────────────────────────────────────────────────── */
    .section-divider { height: 1px; background: var(--color-border); margin-bottom: var(--sp-12); }

    /* ─── Hidden state ────────────────────────────────────────────────────── */
    .post-hidden { display: none !important; }

