<script>
(function () {
  'use strict';

  /* ── State ── */
  let activeCategory = 'all';
  let searchQuery    = '';
  let extraShown     = false;

  /* ── Elements ── */
  const pills        = document.querySelectorAll('#filter-pills .pill');
  const searchInput  = document.getElementById('search-input');
  const newsGrid     = document.getElementById('news-grid');
  const noResults    = document.getElementById('no-results');
  const showMoreBtn  = document.getElementById('show-more-btn');
  const showMoreWrap = document.getElementById('show-more-wrap');
  const extraPosts   = document.querySelectorAll('.post-extra');

  /* ── Filter Logic ── */
  function filterPosts() {
    const cards = newsGrid.querySelectorAll('.news-card:not(#no-results)');
    const q = searchQuery.toLowerCase().trim();
    let visibleCount = 0;

    cards.forEach(card => {
      const cat = card.dataset.category || '';
      const searchable = (card.dataset.searchable || '') + ' ' + (card.querySelector('.card-title')?.textContent || '');
      const isExtra = card.classList.contains('post-extra');

      const categoryMatch = activeCategory === 'all' || cat === activeCategory;
      const searchMatch   = !q || searchable.toLowerCase().includes(q);
      const extraVisible  = !isExtra || extraShown;

      if (categoryMatch && searchMatch && extraVisible) {
        card.classList.remove('post-hidden');
        visibleCount++;
      } else {
        card.classList.add('post-hidden');
      }
    });

    /* Toggle no-results */
    if (visibleCount === 0) {
      noResults.classList.add('visible');
    } else {
      noResults.classList.remove('visible');
    }

    /* Hide show-more if filtered */
    const hasFilterActive = activeCategory !== 'all' || q.length > 0;
    showMoreWrap.style.display = (extraShown || hasFilterActive) ? 'none' : '';
  }

  /* ── Category pills ── */
  pills.forEach(pill => {
    pill.addEventListener('click', () => {
      pills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      activeCategory = pill.dataset.category;
      filterPosts();
    });
  });

  /* ── Search ── */
  searchInput.addEventListener('input', () => {
    searchQuery = searchInput.value;
    filterPosts();
  });

  /* ── Show More ── */
  showMoreBtn.addEventListener('click', () => {
    showMoreBtn.classList.add('loading');
    showMoreBtn.textContent = 'Loading…';

    /* Simulate async feel */
    setTimeout(() => {
      extraShown = true;
      extraPosts.forEach(p => p.classList.remove('post-hidden'));
      showMoreWrap.style.display = 'none';
      showMoreBtn.classList.remove('loading');
      filterPosts();
    }, 380);
  });

  /* ── Dropdowns ── */
  function setupDropdown(btnId, menuId) {
    const btn  = document.getElementById(btnId);
    const menu = document.getElementById(menuId);
    if (!btn || !menu) return;

    function open() {
      menu.classList.add('open');
      btn.setAttribute('aria-expanded', 'true');
      btn.classList.add('dropdown-open');
    }
    function close() {
      menu.classList.remove('open');
      btn.setAttribute('aria-expanded', 'false');
      btn.classList.remove('dropdown-open');
    }
    function toggle() {
      menu.classList.contains('open') ? close() : open();
    }

    btn.addEventListener('click', e => { e.stopPropagation(); toggle(); });

    /* Also open on hover for pointer devices */
    const wrapper = btn.closest('.dropdown-wrapper');
    wrapper.addEventListener('mouseenter', open);
    wrapper.addEventListener('mouseleave', close);

    /* Close on outside click */
    document.addEventListener('click', e => {
      if (!wrapper.contains(e.target)) close();
    });

    /* Keyboard: Escape */
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') close();
    });
  }

  setupDropdown('products-btn',   'products-menu');
  setupDropdown('resources-btn',  'resources-menu');

  /* ── Initial render ── */
  filterPosts();
})();
</script>
